@import url("https://fonts.googleapis.com/css?family=Open+Sans:400,600");
.custom-social-proof {
  position: fixed;
  bottom: 20px;
  left: 20px;
  z-index: 9999999999999 !important;
  font-family: "Open Sans", sans-serif;
}
.custom-social-proof .custom-notification {
  width: 320px;
  border: 0;
  text-align: left;
  z-index: 99999;
  box-sizing: border-box;
  font-weight: 400;
  border-radius: 6px;
  border: 1px solid black;
  box-shadow: 2px 2px 10px 2px rgba(11, 10, 10, 0.2);
  background-color: #fff;
  position: relative;
  cursor: pointer;
}
.custom-social-proof .custom-notification .custom-notification-container {
  display: flex !important;
  align-items: center;
  margin-top: 5px;
  margin-bottom: 5px;
}
.custom-social-proof
  .custom-notification
  .custom-notification-container
  .custom-notification-image-wrapper
  img {
  margin-left: 15px;
  max-height: 75px;
  width: 90px;
  overflow: hidden;
  border-radius: 6px 0 0 6px;
  object-fit: cover;
}
.custom-social-proof
  .custom-notification
  .custom-notification-container
  .custom-notification-content-wrapper {
  margin: 0;
  height: 100%;
  color: gray;
  padding-left: 20px;
  padding-right: 20px;
  border-radius: 0 6px 6px 0;
  flex: 1;
  display: flex !important;
  flex-direction: column;
  justify-content: center;
}
.custom-social-proof
  .custom-notification
  .custom-notification-container
  .custom-notification-content-wrapper
  .custom-notification-content {
  font-family: inherit !important;
  margin: 0 !important;
  padding: 0 !important;
  font-size: 14px;
  line-height: 16px;
}
.custom-social-proof
  .custom-notification
  .custom-notification-container
  .custom-notification-content-wrapper
  .custom-notification-content
  small {
  margin-top: 3px !important;
  display: block !important;
  font-size: 12px !important;
  opacity: 0.8;
}
.custom-social-proof .custom-notification .custom-close {
  position: absolute;
  top: 8px;
  right: 8px;
  height: 12px;
  width: 12px;
  cursor: pointer;
  transition: 0.2s ease-in-out;
  transform: rotate(45deg);
  opacity: 0;
}
.custom-social-proof .custom-notification .custom-close::before {
  content: "";
  display: block;
  width: 100%;
  height: 2px;
  background-color: gray;
  position: absolute;
  left: 0;
  top: 5px;
}
.custom-social-proof .custom-notification .custom-close::after {
  content: "";
  display: block;
  height: 100%;
  width: 2px;
  background-color: gray;
  position: absolute;
  left: 5px;
  top: 0;
}
.custom-social-proof .custom-notification:hover .custom-close {
  opacity: 1;
}

@media (max-width: 320px) {
  .custom-social-proof
    .custom-notification
    .custom-notification-container
    .custom-notification-content-wrapper
    .custom-notification-content {
    line-height: 12px;
  }
  .custom-social-proof
    .custom-notification
    .custom-notification-container
    .custom-notification-content-wrapper
    .custom-notification-content {
    line-height: 12px;
  }
}
@media (max-width: 480px) {
  .custom-social-proof {
    position: fixed;
    bottom: 20px;
    left: 2%;
    right: 2%;
    z-index: 9999999999999 !important;
    font-family: "Open Sans", sans-serif;
  }
  .custom-social-proof .custom-notification {
    width: 90%; /* Increase width to 90% of screen width */
    left: 5%; /* Center the popup */
    bottom: 5%;
  }

  .custom-social-proof
    .custom-notification
    .custom-notification-container
    .custom-notification-content-wrapper
    .custom-notification-content {
    line-height: 18px;
  }

  .custom-social-proof
    .custom-notification
    .custom-notification-container
    .custom-notification-content-wrapper
    .custom-notification-content
    small {
    font-size: 14px; /* Increase font size for the small tag */
  }
}

class YwbPopups {
  names = [
    "Kathleen",
    "Peter",
    "Mia",
    "Rachel",
    "Henry",
    "William",
    "Nicole",
    "Charlie",
    "Mary",
    "Ann",
    "Thomas",
    "John",
    "James",
    "Paul",
    "Jorge",
    "Jack",
    "William",
    "Nicole",
    "Charlie",
  ];
  cities = [
    "Auckland",
    "Wellington",
    "Christchurch",
    "Hamilton",
    "Tauranga",
    "Napier-Hastings",
    "Dunedin",
    "Palmerston North",
    "Nelson",
    "Rotorua",
    "Whangarei",
    "New Plymouth",
    "Invercargill",
    "Whanganui",
    "Gisborne",
    "Timaru",
    "Blenheim",
    "Pukekohe",
    "Masterton",
    "Ashburton",
  ];
  minutes = [
    28, 25, 24, 22, 20, 19, 17, 16, 15, 13, 11, 10, 8, 7, 6, 4, 2, 1, 1,
  ];
  productName = "Dell Inspiron";
  productImage = "slider/product1.png";

  dataIndex = 0;
  socialProof;
  socialContent;

  showPopups = true;

  addSocialProofBlock() {
    const socialProof = document.createElement("section");
    socialProof.className = "custom-social-proof";
    socialProof.style.display = "none";
    document.body.appendChild(socialProof);

    const notification = document.createElement("div");
    notification.className = "custom-notification";
    socialProof.appendChild(notification);

    const container = document.createElement("div");
    container.className = "custom-notification-container";
    notification.appendChild(container);

    const imageWrapper = document.createElement("div");
    imageWrapper.className = "custom-notification-image-wrapper";
    container.appendChild(imageWrapper);

    const img = document.createElement("img");
    img.src = this.productImage;
    imageWrapper.appendChild(img);

    const contentWrapper = document.createElement("div");
    contentWrapper.className = "custom-notification-content-wrapper";
    container.appendChild(contentWrapper);

    const content = document.createElement("p");
    content.className = "custom-notification-content";
    contentWrapper.appendChild(content);

    const closeBtn = document.createElement("div");
    closeBtn.className = "custom-close";
    closeBtn.addEventListener("click", function() {
      socialProof.style.display = "none";
    });
    notification.appendChild(closeBtn);
  }

  addStyles() {
    const linkElement = document.createElement("link");
    linkElement.rel = "stylesheet";
    linkElement.href = "ywbpurchasepopup.css";
    document.head.appendChild(linkElement);
  }

  showPopup() {
    if (!this.showPopups) return;
    this.socialContent.innerHTML = `
      ${this.names[this.dataIndex]} from ${this.cities[this.dataIndex]}<br>
      got a chance to purchase<br>
      <b>${this.productName}</b> for $3.00<br>
      <small>${this.minutes[this.dataIndex]} minutes ago</small>`;
    this.socialProof.style.display = "block";
    this.dataIndex = (this.dataIndex + 1) % this.names.length;
  }

  switchOff() {
    this.showPopups = false;
  }

  getRandomInterval(min, max) {
    return Math.floor(Math.random() * (max - min + 1) + min) * 1000; // Convert to milliseconds
  }

  togglePopup = () => {
    if (this.socialProof.style.display === "block") {
      this.socialProof.style.display = "none";
    } else {
      this.showPopup();
    }
    setTimeout(() => this.togglePopup(), this.getRandomInterval(8, 25)); // Set the next timeout with a random interval
  };

  constructor() {
    document.addEventListener("DOMContentLoaded", () => {
      this.addSocialProofBlock();
      this.addStyles();
      this.dataIndex = 0;

      this.socialProof = document.querySelector(".custom-social-proof");
      this.socialContent = document.querySelector(
        ".custom-notification-content",
      );

      setTimeout(() => this.togglePopup(), this.getRandomInterval(1, 5));
    });
  }
}

const ywbPopups = new YwbPopups();
